package com.hbm.client.bomb.nuclear;
import com.mojang.blaze3d.vertex.VertexConsumer;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import net.minecraft.client.Camera;import net.minecraft.client.multiplayer.ClientLevel;import net.minecraft.client.particle.*;import net.minecraft.world.phys.AABB;
/** Original stationary ParticleContrail: six seeded full-bright puffs,100..139ticks and source fade/scale. */
public final class LegacyAbmContrailParticle extends Particle implements SourceSmokeGeometry{private static final AtomicInteger IDS=new AtomicInteger();private final int seed=IDS.incrementAndGet();private float particleAlpha=1;private final float baseRed,baseGreen,baseBlue,sourceScale;public LegacyAbmContrailParticle(ClientLevel world,double x,double y,double z){this(world,x,y,z,0,0,0,1);}public LegacyAbmContrailParticle(ClientLevel world,double x,double y,double z,float red,float green,float blue,float scale){super(world,x,y,z);baseRed=red;baseGreen=green;baseBlue=blue;sourceScale=scale;lifetime=100+random.nextInt(40);xd=yd=zd=0;}@Override public void tick(){xo=x;yo=y;zo=z;particleAlpha=1-(float)age/lifetime;if(++age==lifetime)remove();}@Override public ParticleRenderType getRenderType(){return MukeRenderTypes.ORDERED;}@Override public AABB getRenderBoundingBox(float partial){return new AABB(x-5,y-5,z-5,x+5,y+5,z+5);}@Override public ParticleRenderType smokeMaterial(){return MukeRenderTypes.CONTRAIL;}@Override public void render(VertexConsumer ignored,Camera camera,float partial){if(MukeRenderTypes.defer(this,partial))return;emitSmokeGeometry(MukeRenderTypes.begin(smokeMaterial()),camera,partial);}@Override public void emitSmokeGeometry(VertexConsumer out,Camera camera,float partial){var eye=camera.getPosition();var shape=new Random(seed);for(int i=0;i<6;i++){float gray=shape.nextFloat()*.2F+.2F;float size=(particleAlpha+.5F)*sourceScale;float px=(float)(xo+(x-xo)*partial-eye.x+shape.nextGaussian()*.5*sourceScale),py=(float)(yo+(y-yo)*partial-eye.y+shape.nextGaussian()*.5*sourceScale),pz=(float)(zo+(z-zo)*partial-eye.z+shape.nextGaussian()*.5*sourceScale);MukeClient.billboard(out,camera,px,py,pz,size,baseRed+gray,baseGreen+gray,baseBlue+gray,particleAlpha,0,1,0,1,false,true);}}}
